const state={user:null,bootstrap:null,setupRequired:false,setupToken:'',setupTokenFromLink:false,offlineResume:false,lang:localStorage.getItem('ithomiini.lang')||'es',page:'daily',params:{},busy:false,notice:null,query:'',module:null,record:null,scan:null,selectedChanges:new Set(),sourceFilter:'',mobileMenu:false};
function t(key){return I[state.lang]?.[key]||I.es[key]||key}
function tr(es,en){return state.lang==='en'?(en||es):es}
function mod(id){return state.bootstrap?.modules?.find(m=>m.id===id||m.sheet===id)}
function moduleForSheet(sheet){return state.bootstrap?.modules?.find(m=>m.sheet===sheet)}
function moduleName(m){return state.lang==='en'?(m?.labelEn||m?.label||m?.sheet):(m?.label||m?.sheet)||''}
function objectText(value){if(value==null)return '—';if(typeof value==='object')return JSON.stringify(value);return String(value)}
function displayFieldValue(module,key,value){return module?.fields?.find(field=>field.key===key)?.type==='date'?fmtDate(value):objectText(value)}
function actorText(action){return action.actorName||action.actorDisplayName||(action.source==='external'?tr('Editor no identificado','Editor unknown'):tr('Editor registrado','Recorded editor'))}
function groupName(group){return ({field:tr('Campo','Field'),insectary:tr('Insectario','Insectary'),breeding:tr('Cruces','Breeding'),research:tr('Experimentos','Research'),samples:tr('Muestras','Samples'),media:tr('Fotos','Media'),reference:tr('Referencias','Reference'),Campo:tr('Campo','Field'),Individuos:tr('Individuos','Individuals'),Insectario:tr('Insectario','Insectary'),Cruces:tr('Cruces','Breeding'),Experimentos:tr('Experimentos','Experiments'),Muestras:tr('Muestras','Samples'),Revisión:tr('Revisión','Review')})[group]||group}
