function safeHref(raw){if(typeof raw!=='string'||!/^https?:\/\//i.test(raw.trim()))return '';try{const u=new URL(raw);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function notify(message,type='success'){state.notice={message,type};renderNotice();setTimeout(()=>{if(state.notice?.message===message){state.notice=null;renderNotice()}},6500)}
function renderNotice(){document.getElementById('notice-host')?.replaceChildren();const host=document.getElementById('notice-host');if(!host||!state.notice)return;host.innerHTML=`<div class="toast ${esc(state.notice.type)}" role="status">${icon(state.notice.type==='error'?'alert':'check',18)}<span>${esc(state.notice.message)}</span><button class="icon-button" data-action="dismiss-notice" aria-label="Cerrar">${icon('close',16)}</button></div>`}
function route(path){location.hash='#'+path}
function getRoute(){const raw=decodeURIComponent(location.hash.replace(/^#/,'')||'/daily');const [path,query='']=raw.split('?');return {parts:path.split('/').filter(Boolean),query:new URLSearchParams(query)}}
function currentLabel(){return state.bootstrap?.settings?.sandboxLabel||state.bootstrap?.settings?.label||t('test')}
function navLink(page,label,ico){return `<a href="#/${page}" class="nav-link ${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(ico,19)}<span>${esc(label)}</span></a>`}
