function pageHead(title,subtitle='',actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><div class="head-actions">${actions}</div></div>`}
function empty(message,action=''){return `<div class="empty-state">${icon('book',28)}<h2>${esc(message)}</h2>${action}</div>`}
function loading(){return `<div class="loading">${icon('sync',22)} ${esc(t('loading'))}</div>`}
function errorBox(error){return `<div class="message error" role="alert">${icon('alert',18)}<span>${esc(error?.message||error||'Ocurrió un error.')}</span><button class="button button-small" data-action="refresh">${tr('Reintentar','Retry')}</button></div>`}
function pill(status){return `<span class="status-pill ${esc(status||'neutral')}">${esc(statusLabel(status))}</span>`}
function moduleCards(modules){return `<div class="module-grid">${modules.map(m=>`<a class="module-row" href="#/module/${encodeURIComponent(m.id)}"><span><strong>${esc(moduleName(m))}</strong><small>${esc(m.sheet||m.group||'')}${typeof m.recordCount==='number'?` · ${m.recordCount.toLocaleString()}`:''}</small></span>${icon('chevron',18)}</a>`).join('')}</div>`}
function rememberOfflineSession(){if(!state.user?.id||!state.bootstrap?.modules)return;const id=String(state.user.id);const metadata={user:{id,username:state.user.username,displayName:state.user.displayName,role:state.user.role},modules:state.bootstrap.modules,settings:{sandboxLabel:state.bootstrap.settings?.sandboxLabel,sheetUrl:state.bootstrap.settings?.sheetUrl}};try{localStorage.setItem(`ithomiini.resume.v1:${id}`,JSON.stringify(metadata));localStorage.setItem('ithomiini.resume.lastOwner.v1',id)}catch{}}
function restoreOfflineSession(){try{const id=localStorage.getItem('ithomiini.resume.lastOwner.v1');if(!id)return false;const saved=JSON.parse(localStorage.getItem(`ithomiini.resume.v1:${id}`)||'null');if(!saved?.user?.id||String(saved.user.id)!==id||!Array.isArray(saved.modules))return false;state.user=saved.user;state.bootstrap={user:saved.user,modules:saved.modules,settings:saved.settings||{},sync:{status:'offline_unverified'}};state.offlineResume=true;setCsrf('');setUserScope(id);return true}catch{return false}}
function clearOfflineResume(){const id=localStorage.getItem('ithomiini.resume.lastOwner.v1');if(id)localStorage.removeItem(`ithomiini.resume.v1:${id}`);localStorage.removeItem('ithomiini.resume.lastOwner.v1')}
async function loadSession(){try{const session=await request('/api/auth/session');state.user=session.user;state.setupRequired=!!session.setupRequired;setCsrf(session.csrf);if(localStorage.getItem('ithomiini.pendingLogout.v1')){if(session.user)await request('/api/auth/logout',{method:'POST'});localStorage.removeItem('ithomiini.pendingLogout.v1');state.user=null;state.offlineResume=false;setUserScope(null);setCsrf('');renderAuth(false);return false}if(session.setupRequired){state.offlineResume=false;renderAuth(true);return false}if(!session.user){state.offlineResume=false;setUserScope(null);renderAuth(false);return false}setUserScope(session.user.id);const boot=await request('/api/bootstrap');state.bootstrap=boot;state.user=boot.user||session.user;state.offlineResume=false;setUserScope(state.user.id);setCsrf(boot.csrf||session.csrf);rememberOfflineSession();return true}catch(error){if(error.status===401){state.offlineResume=false;setUserScope(null);renderAuth(false);return false}if(error.code==='network'&&restoreOfflineSession())return true;renderAuth(false,error.message);return false}}
function renderAuth(setup=false,error=''){const setupToken=setup&&location.hash.startsWith('#/setup?')?new URLSearchParams(location.hash.split('?')[1]||'').get('token'):null;if(setupToken){state.setupToken=setupToken;state.setupTokenFromLink=true}$app.innerHTML=`<div class="auth-page"><div class="auth-art"><div class="auth-inner"><div class="auth-wordmark"><span class="auth-mark">${icon('layers',32)}</span>Ithomiini</div><div class="auth-illustration" aria-hidden="true"><svg viewBox="0 0 500 430"><path d="M250 50v323M100 191c54-85 104-85 150 0-61 6-104 37-150 0Zm300 0c-54-85-104-85-150 0 61 6 104 37 150 0ZM160 270c33-36 63-38 90-2-36 5-66 30-90 2Zm180 0c-33-36-63-38-90-2 36 5 66 30 90 2Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M250 68c-31 11-58 41-74 93M250 68c31 11 58 41 74 93M250 270c-18 14-32 33-39 59M250 270c18 14 32 33 39 59" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="250" cy="49" r="6" fill="currentColor"/></svg></div><p>${tr('Un registro vivo de campo,','A living record of fieldwork,')}<br>${tr('insectario e investigación.','insectary and research.')}</p><small>${esc(t('test'))}</small></div></div><div class="auth-form-side"><div class="auth-form-wrap"><span class="auth-kicker">${tr('Cuaderno de trabajo','Working notebook')}</span><h1>${setup?tr('Configurar acceso','Set up access'):tr('Bienvenido de nuevo','Welcome back')}</h1><p>${setup?tr('Crea la cuenta administradora para esta copia personal.','Create the administrator account for this personal copy.'):tr('Accede para registrar observaciones y revisar el historial.','Sign in to record observations and review history.')}</p>${error?`<div class="message error" role="alert">${esc(error)}</div>`:''}<div class="stack-form">${setup&&!state.setupTokenFromLink?`<label for="setup-token">${tr('Token de configuración','Setup token')}<input id="setup-token" form="auth-form" name="token" type="text" required autocomplete="off" value="${esc(state.setupToken)}"></label>`:''}<form id="auth-form" class="stack-form" method="post" action="${apiUrl(setup?'/api/auth/setup':'/api/auth/login')}">${setup?`${state.setupTokenFromLink?`<input name="token" type="hidden" value="${esc(state.setupToken)}">`:''}<label for="auth-display-name">${tr('Nombre visible','Display name')}<input id="auth-display-name" name="displayName" type="text" required autocomplete="name"></label>`:''}<label for="auth-username">${tr('Usuario','Username')}<input id="auth-username" name="username" type="text" required autocomplete="username"></label><label for="auth-password">${tr('Contraseña','Password')}<input id="auth-password" name="password" type="password" required ${setup?'minlength="6" maxlength="16"':''} autocomplete="${setup?'new-password':'current-password'}"></label><button class="button button-primary button-wide" type="submit">${setup?tr('Crear cuenta y entrar','Create account and sign in'):tr('Entrar','Sign in')} ${icon('chevron',17)}</button></form></div><div class="auth-language"><button data-action="language" data-lang="es" ${state.lang==='es'?'aria-current="true"':''}>Español</button><span>·</span><button data-action="language" data-lang="en" ${state.lang==='en'?'aria-current="true"':''}>English</button></div></div></div></div>`;if(setupToken)history.replaceState(null,'',location.pathname+location.search+'#/setup')}
async function renderRoute(){if(!state.user)return;const {parts,query}=getRoute();state.page=parts[0]||'daily';state.params={parts,query};state.mobileMenu=false;shell(loading());try{let html;
  switch(state.page){case 'daily':html=await dailyPage();break;case 'register':html=await registerPage(query);break;case 'module':html=await modulePage(parts[1],query);break;case 'record':html=await recordPage(parts[1]);break;case 'form':html=await formPage(parts[1],parts[2]);break;case 'workflows':html=workflowPage();break;case 'workflow':html=await workflowDetail(parts[1]);break;case 'tasks':html=await tasksPage();break;case 'explore':html=await explorePage(query);break;case 'history':html=await historyPage(query);break;case 'assistant':html=await assistantPage(parts[1]);break;case 'settings':html=await settingsPage(parts[1]);break;case 'import':html=await importPage(parts[1]);break;default:html=empty('Esta página no existe.',`<a class="button" href="#/daily">Volver a Hoy</a>`)}
  document.getElementById('main-content')?.replaceChildren();document.getElementById('main-content').innerHTML=html;document.title=`${document.querySelector('h1')?.textContent||'Ithomiini'} · Ithomiini`;afterRender();
}catch(error){document.getElementById('main-content').innerHTML=errorBox(error)}}
let subspeciesSequence=0;
async function refreshSubspeciesOptions(form){
  if(form?.dataset.module!=='Collection_data'||state.offlineResume)return;
  const species=form.elements.namedItem('SPECIES');
  const subspecies=form.elements.namedItem('Subspecies_Form');
  const list=subspecies?.getAttribute('list')&&document.getElementById(subspecies.getAttribute('list'));
  if(!species||!subspecies||!list)return;
  const selected=species.value.trim();
  const sequence=++subspeciesSequence;
  list.replaceChildren();
  if(!selected)return;
  try{
    const data=await request(`/api/options?module=Collection_data&field=Subspecies_Form&species=${encodeURIComponent(selected)}`);
    if(sequence!==subspeciesSequence||!form.isConnected||species.value.trim()!==selected)return;
    const choices=Array.isArray(data.options)?data.options:[];
    list.replaceChildren(...choices.map(item=>{const option=document.createElement('option');option.value=String(typeof item==='object'?(item.value??item.label??''):item);return option}));
  }catch{ /* Manual entry remains available if suggestions are unavailable. */ }
}
function afterRender(){const autofocus=document.querySelector('[data-autofocus]');if(autofocus&&matchMedia('(min-width: 760px)').matches)autofocus.focus({preventScroll:true});const recordForm=document.getElementById('record-form');if(recordForm)refreshSubspeciesOptions(recordForm);const quick=document.querySelector('#core-status-form,#capture-form,#emergence-form');if(quick){const key=`quick:${quick.id}:${quick.dataset.kind||''}`;const draft=getDraft(key)?.value||{};for(const [name,value] of Object.entries(draft)){if(name==='recordId')continue;const control=quick.elements.namedItem(name);if(control&&'value'in control)control.value=value}if(Object.keys(draft).length)updateFormState(tr('Borrador recuperado; confirma la identidad','Draft restored; confirm identity'))}if(state.page==='workflow'&&state.params.parts[1]==='emergence')renderBatchIndividuals();const pending=sessionStorage.getItem('ithomiini.pendingPrompt');if(pending&&state.page==='assistant'){const input=document.getElementById('chat-input');if(input){input.value=pending;input.focus();sessionStorage.removeItem('ithomiini.pendingPrompt')}}}
async function dailyPage(){const [tasksResult,historyResult,collectionResult,insectaryResult]=await Promise.allSettled([request('/api/tasks'),request('/api/history?limit=8'),request('/api/records?module=Collection_data&observedOnly=true&limit=8'),request('/api/records?module=Insectary_data&observedOnly=true&limit=8')]);const tasks=tasksResult.status==='fulfilled'?(tasksResult.value.tasks||[]):[];const actions=historyResult.status==='fulfilled'?(historyResult.value.actions||[]):[];const recent=[...(collectionResult.status==='fulfilled'?(collectionResult.value.records||[]):[]),...(insectaryResult.status==='fulfilled'?(insectaryResult.value.records||[]):[])].filter(record=>record.observed!==false).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||''))).slice(0,8);const open=tasks.filter(task=>!['done','completed','cancelled'].includes(task.status));const today=new Date().toLocaleDateString(state.lang==='en'?'en-GB':'es-EC',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Guayaquil'});const ready=state.bootstrap?.sync;
  return `${pageHead(tr('Hoy en la estación','Today at the station'),today,`<a class="button button-primary" href="#/workflows">${icon('plus',17)} ${tr('Registrar trabajo','Record work')}</a>`)}<div class="daily-layout"><section class="daily-main"><div class="section-head"><h2>${tr('Trabajo por hacer','Work to do')}</h2><a href="#/tasks">${tr('Ver todas las tareas','All tasks')} ${icon('chevron',15)}</a></div>${open.length?`<div class="task-list">${open.slice(0,8).map(task=>taskRow(task)).join('')}</div>`:empty(tr('No hay tareas abiertas.','No open tasks.'),`<a class="button button-small" href="#/tasks">${tr('Crear una tarea','Create a task')}</a>`)}<div class="section-head section-space"><h2>${tr('Actividad reciente','Recent activity')}</h2><a href="#/history">${tr('Historial completo','Full history')} ${icon('chevron',15)}</a></div>${actions.length?`<div class="activity-list">${actions.map(action=>activityRow(action)).join('')}</div>`:empty(tr('Aún no hay cambios registrados.','No changes recorded yet.'))}</section><aside class="daily-side"><div class="side-panel"><h2>${tr('Acciones frecuentes','Frequent actions')}</h2><div class="quick-links">${['capture','round','emergence','sample'].map(id=>{const w=workflowSpecs.find(v=>v.id===id);return `<a href="#/workflow/${id}">${icon(id==='capture'?'map':id==='sample'?'flask':'layers',18)}<span>${esc(tr(w.title,w.en))}</span>${icon('chevron',15)}</a>`}).join('')}</div></div><div class="side-panel"><div class="side-head"><h2>${tr('Últimos registros','Recent records')}</h2><a href="#/register">${tr('Ver todos','View all')}</a></div>${recent.length?recent.slice(0,5).map(record=>`<a class="mini-record" href="#/record/${encodeURIComponent(record.id)}"><strong>${esc(recordTitle(record,moduleForSheet(record.sheet)))}</strong><small>${esc(moduleName(moduleForSheet(record.sheet))||record.sheet)}</small></a>`).join(''):'<p class="muted">No hay registros recientes.</p>'}</div><div class="sync-note">${icon('sync',17)}<span>${ready?.lastSyncAt?`Última sincronización: ${esc(fmtTime(ready.lastSyncAt))}`:tr('Estado de sincronización disponible en Ajustes.','Sync status in Settings.')}</span></div></aside></div>`}
function taskRow(task){const due=task.dueDate?fmtDate(task.dueDate):'';return `<div class="task-row"><button class="task-check" data-action="complete-task" data-id="${esc(task.id)}" aria-label="Completar ${esc(task.title)}">${icon('check',16)}</button><div><strong>${esc(task.title||'Tarea')}</strong>${task.description?`<p>${esc(task.description)}</p>`:''}<small>${due?`<span>${icon('clock',13)} ${esc(due)}</span>`:''}${task.assignee?`<span>${esc(task.assignee)}</span>`:''}</small></div>${task.recordId?`<a href="#/record/${encodeURIComponent(task.recordId)}" class="row-arrow" aria-label="Ver registro">${icon('chevron',17)}</a>`:''}</div>`}
