async function registerPage(query){const q=query.get('q')||'';const data=state.offlineResume?{records:[],total:0}:await request(`/api/records?limit=30${q?`&q=${encodeURIComponent(q)}`:''}`);return `${pageHead(t('register'),tr('Busca en todas las hojas y elige el registro correcto.','Search across sheets and choose the right record.'),`<button class="button button-primary" data-action="new-record">${icon('plus',17)} ${t('new')}</button>`)}<form class="inline-search" id="register-search"><label class="sr-only" for="register-q">Buscar registros</label>${icon('search',19)}<input id="register-q" name="q" value="${esc(q)}" placeholder="${esc(t('search'))}" data-autofocus ${state.offlineResume?'disabled':''}><button class="button button-small" type="submit" ${state.offlineResume?'disabled':''}>${tr('Buscar','Search')}</button><button type="button" class="icon-button" data-action="scan" title="Escanear etiqueta" aria-label="Escanear etiqueta" ${state.offlineResume?'disabled':''}>${icon('camera',19)}</button></form>${state.offlineResume?`<div class="message pending">${tr('La búsqueda requiere conexión. Puedes abrir un formulario nuevo desde las áreas de abajo y guardar un borrador local.','Search requires a connection. Open a new form from the areas below and save a local draft.')}</div>`:''}${q&&!state.offlineResume?`<p class="results-caption">${data.total??data.records?.length??0} ${tr('coincidencias. Las marcas pueden repetirse; comprueba hoja, fecha y origen.','matches. Marks may repeat; check sheet, date and origin.')}</p>`:''}${!state.offlineResume?recordList(data.records||[]):''}${data.total>(data.records||[]).length?`<button class="button load-more" data-action="load-more-records" data-offset="30" data-q="${esc(q)}">${t('more')}</button>`:''}<div class="section-head section-space"><h2>${tr('Explorar por área','Browse by area')}</h2></div>${moduleDirectory()}`}
function recordList(records){if(!records.length)return empty(t('empty'));return `<div class="record-list" id="record-list">${records.map(record=>{const module=moduleForSheet(record.sheet);const primary=primaryValues(record,module,3);return `<a class="record-row" href="#/record/${encodeURIComponent(record.id)}"><span class="record-symbol">${icon(record.sheet?.toLowerCase().includes('insect')?'layers':'book',19)}</span><span class="record-core"><strong>${esc(recordTitle(record,module))}</strong><small>${esc(moduleName(module)||record.sheet)}${record.row?` · ${tr('fila','row')} ${esc(record.row)}`:''}</small><span class="record-facts">${primary.map(item=>`<span>${esc(item.label)} <b>${esc(displayFieldValue(module,item.key,item.value))}</b></span>`).join('')}</span></span>${icon('chevron',18)}</a>`}).join('')}</div>`}
function moduleDirectory(){const groups=Object.groupBy?Object.groupBy(state.bootstrap?.modules||[],m=>m.group||'Otras hojas'):((state.bootstrap?.modules||[]).reduce((a,m)=>((a[m.group||'Otras hojas']??=[]).push(m),a),{}));return Object.entries(groups).map(([group,modules])=>`<section class="directory-group"><h3>${esc(groupName(group))}</h3>${moduleCards(modules)}</section>`).join('')}
async function modulePage(id,query){const m=mod(id);if(!m)return empty('No se encontró esta hoja.');const q=query.get('q')||'';const offset=Number(query.get('offset')||0);const data=state.offlineResume?{records:[],total:0}:await request(`/api/records?module=${encodeURIComponent(m.id)}&limit=40&offset=${offset}${q?`&q=${encodeURIComponent(q)}`:''}`);return `<div class="breadcrumb"><a href="#/register">${t('register')}</a>${icon('chevron',14)}<span>${esc(moduleName(m))}</span></div>${pageHead(moduleName(m),`${m.sheet||''} · ${data.total??m.recordCount??0} ${tr('registros','records')}`,`<a class="button" href="#/import/${encodeURIComponent(m.id)}">${icon('upload',16)} ${tr('Importar','Import')}</a><button class="button" data-action="export" data-module="${esc(m.id)}">${icon('download',16)} CSV</button><a class="button button-primary" href="#/form/${encodeURIComponent(m.id)}/new">${icon('plus',16)} ${tr('Añadir','Add')}</a>`)}<form class="inline-search" id="module-search" data-module="${esc(m.id)}">${icon('search',18)}<input name="q" value="${esc(q)}" placeholder="Buscar en ${esc(moduleName(m))}"><button class="button button-small" type="submit">${tr('Buscar','Search')}</button></form>${recordList(data.records||[])}${data.total>offset+(data.records||[]).length?`<a class="button load-more" href="#/module/${encodeURIComponent(m.id)}?q=${encodeURIComponent(q)}&offset=${offset+40}">${t('more')}</a>`:''}`}
