function workflowPage(){const groups=Object.groupBy?Object.groupBy(workflowSpecs,w=>w.group):workflowSpecs.reduce((a,w)=>((a[w.group]??=[]).push(w),a),{});return `${pageHead(t('workflows'),tr('Registra la observación en el momento y conserva su fuente.','Record an observation at the time it happens and keep its source.'))}<div class="workflow-intro"><p>${tr('Cada operación crea un evento fechado y atribuible. El registro original de la hoja sigue disponible para sus campos completos.','Each operation creates a dated, attributable event. The original sheet remains available for its full fields.')}</p></div>${Object.entries(groups).map(([group,items])=>`<section class="workflow-group"><h2>${esc(groupName(group))}</h2><div class="workflow-grid">${items.map(w=>`<a class="workflow-card" href="#/workflow/${w.id}"><span class="workflow-icon">${icon(['Campo','Individuos'].includes(group)?'map':group==='Muestras'?'flask':group==='Experimentos'?'spark':'layers',21)}</span><span><strong>${esc(tr(w.title,w.en))}</strong><small>${esc(workflowSummary(w))}</small></span>${icon('chevron',17)}</a>`).join('')}</div></section>`).join('')}`}
function eventField(field,index,prior){const id=`event-${index}`;const name=field;const lower=field.toLowerCase();let type=lower.includes('fecha')?'date':lower.includes('hora')?'time':/huevos|larvas|pupas|adultos|cantidad|concentración|260\/|eclosionados|preservados/.test(lower)?'number':'text';const val=prior?.[name]||'';const multiline=/notas|evidencia|observación/.test(lower);return `<div class="field"><label for="${id}">${esc(field)}</label>${multiline?`<textarea id="${id}" name="${esc(name)}" rows="3">${esc(val)}</textarea>`:`<input id="${id}" name="${esc(name)}" type="${type}" value="${esc(val)}" ${type==='number'?'min="0" step="any"':''} ${index===0?'data-autofocus':''}>`}</div>`}
async function workflowDetail(id){const w=workflowSpecs.find(item=>item.id===id);if(!w)return empty('No se encontró esta operación.');if(['death','preserve','capture','emergence'].includes(id))return coreWorkflowPage(w);const m=moduleForSheet(w.sheet);const draft=getDraft(`event:${w.kind}`);const eventsResult=await Promise.allSettled([request(`/api/events?kind=${encodeURIComponent(w.kind)}`)]);const events=eventsResult[0].status==='fulfilled'?(eventsResult[0].value.events||[]):[];return `<div class="breadcrumb"><a href="#/workflows">${t('workflows')}</a>${icon('chevron',14)}<span>${esc(tr(w.title,w.en))}</span></div>${pageHead(tr(w.title,w.en),workflowSummary(w),`${m?`<a class="button" href="#/module/${encodeURIComponent(m.id)}">${icon('book',16)} ${tr('Abrir hoja','Open sheet')}</a>`:''}`)}<div class="editor-layout"><form id="event-form" class="editor-form" data-kind="${esc(w.kind)}"><div class="form-banner">${icon('clock',17)}<span>${tr('Nueva observación · fuente: aplicación','New observation · source: app')}</span></div>${draft?`<div class="message pending">${icon('clock',17)} ${tr('Borrador local recuperado','Local draft restored')}</div>`:''}<div class="form-section-heading"><h2>${tr('Registrar operación','Record operation')}</h2><p>${tr('Escribe lo observado. Los cálculos e inferencias requieren una revisión aparte.','Enter what was observed. Calculations and inferences require separate review.')}</p></div><div class="fields-grid">${w.fields.map((field,index)=>eventField(field,index,draft?.value)).join('')}</div><div class="form-footer"><div class="form-state" id="form-state">${icon('check',16)} ${draft?tr('Borrador local','Local draft'):tr('Listo para registrar','Ready to record')}</div><div><a class="button" href="#/workflows">${t('cancel')}</a><button class="button button-primary" type="submit">${icon('check',17)} ${tr('Registrar observación','Record observation')}</button></div></div></form><aside class="editor-side"><div class="side-panel"><h2>${tr('Registros de la hoja','Sheet records')}</h2><p>${tr('El evento queda vinculado a un registro cuando indicas su ID. Los campos originales también se pueden completar en la hoja correspondiente.','Link the event to a record with its app ID. You can also edit original fields in the corresponding sheet.')}</p><label class="compact-label">ID del registro relacionado<input id="event-record-id" placeholder="ID de la app" value="${esc(draft?.value?.recordId||'')}"></label>${m?`<a href="#/form/${encodeURIComponent(m.id)}/new">${tr('Nuevo registro en','New record in')} ${esc(moduleName(m))} ${icon('chevron',14)}</a>`:''}</div><div class="side-panel"><h2>${tr('Últimas observaciones','Recent observations')}</h2>${events.length?events.slice(0,6).map(event=>`<div class="mini-event"><strong>${esc(fmtDate(event.createdAt||event.date))}</strong><small>${esc(Object.values(event.values||{}).slice(0,2).join(' · '))}</small></div>`).join(''):'<p class="muted">Sin observaciones recientes.</p>'}</div></aside></div>`}
async function tasksPage(){const data=await request('/api/tasks');const tasks=data.tasks||[];const open=tasks.filter(task=>!['done','completed','cancelled'].includes(task.status));const done=tasks.filter(task=>['done','completed'].includes(task.status));return `${pageHead(tr('Tareas del equipo','Team tasks'),tr('Seguimiento de rondas, revisiones y trabajo pendiente.','Track rounds, reviews and pending work.'),`<button class="button button-primary" data-action="show-task-form">${icon('plus',17)} ${tr('Nueva tarea','New task')}</button>`)}<form id="task-form" class="compact-form hidden"><div class="fields-grid"><div class="field"><label for="task-title">Título</label><input id="task-title" name="title" required></div><div class="field"><label for="task-date">Fecha límite</label><input id="task-date" name="dueDate" type="date"></div><div class="field"><label for="task-assignee">Responsable</label><input id="task-assignee" name="assignee"></div><div class="field"><label for="task-record">ID de registro</label><input id="task-record" name="recordId"></div><div class="field span-full"><label for="task-description">Detalles</label><textarea id="task-description" name="description" rows="2"></textarea></div></div><button class="button button-primary" type="submit">${tr('Crear tarea','Create task')}</button></form><div class="section-head"><h2>${tr('Abiertas','Open')}</h2><span class="count-label">${open.length}</span></div>${open.length?`<div class="task-list">${open.map(taskRow).join('')}</div>`:empty(tr('No hay tareas abiertas.','No open tasks.'))}<div class="section-head section-space"><h2>${tr('Completadas','Completed')}</h2><span class="count-label">${done.length}</span></div>${done.length?`<div class="task-list completed">${done.slice(0,20).map(taskRow).join('')}</div>`:'<p class="muted">Sin tareas completadas.</p>'}`}
function chartSvg(series){const definition=Array.isArray(series)&&series[0]?.data?series[0]:null;const points=definition?definition.data:(Array.isArray(series)?series:[]);const xKey=definition?.x||'label',yKey=definition?.y||'value';const vals=points.map(p=>Number(p[yKey]??p.value??p.count??0)).filter(Number.isFinite);if(!vals.length)return empty('No hay datos para la gráfica.');const max=Math.max(...vals,1);const bars=points.slice(0,16).map((p,i)=>{const n=Number(p[yKey]??p.value??p.count??0);const x=18+i*(660/Math.min(points.length,16)),width=Math.max(15,660/Math.min(points.length,16)-10),h=Math.max(2,(n/max)*190);return `<g><rect x="${x}" y="${220-h}" width="${width}" height="${h}" rx="3" fill="#386f5d"/><text x="${x+width/2}" y="${214-h}" text-anchor="middle" font-size="11" fill="#24473d">${esc(n)}</text><text x="${x+width/2}" y="244" text-anchor="middle" font-size="10" fill="#496258">${esc(String(p[xKey]??p.label??i+1).slice(0,11))}</text></g>`}).join('');return `<div class="chart-wrap"><svg viewBox="0 0 700 270" role="img" aria-label="Gráfica de barras de los resultados"><path d="M18 220H680" stroke="#a9bcb2"/>${bars}</svg></div>`}
function reportTable(report){const columns=report.columns||Object.keys(report.rows?.[0]||{});const rows=report.rows||[];return `<div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th scope="col">${esc(typeof c==='object'?c.label||c.key:c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>{const key=typeof c==='object'?c.key:c;return `<td>${esc(plain(row[key]))}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
async function explorePage(query){const view=query.get('view')||'table';const kind=query.get('kind')||'overview';const moduleId=query.get('module')||'';let body='';if(view==='gallery')body=await galleryView(query);else if(view==='map')body=await mapView(query);else{try{const report=await request(`/api/reports?kind=${encodeURIComponent(kind)}${moduleId?`&module=${encodeURIComponent(moduleId)}`:''}`);body=`<div class="report-header"><div><h2>${esc(report.title||tr('Resultados','Results'))}</h2><p>${esc(report.method||'')}${report.generatedAt?` · ${esc(fmtTime(report.generatedAt))}`:''}</p></div></div>${view==='chart'?chartSvg(report.series||[]):reportTable(report)}${(report.sources||[]).length?`<details class="sources"><summary>${tr('Fuentes','Sources')} (${report.sources.length})</summary>${report.sources.map(s=>`<div>${s.id?`<a href="#/record/${encodeURIComponent(s.id)}">${esc(s.sheet||'Registro')} · ${tr('fila','row')} ${esc(s.row||'—')}</a>`:esc(typeof s==='string'?s:s.label||s.sheet||JSON.stringify(s))}${safeHref(s.sourceUrl)?` · <a href="${esc(safeHref(s.sourceUrl))}" target="_blank" rel="noopener noreferrer">${tr('Hoja','Sheet')}</a>`:''}</div>`).join('')}</details>`:''}`;}catch(error){body=errorBox(error)}}return `${pageHead(t('explore'),tr('Informes y vistas con datos de la fuente actual.','Reports and views from current source data.'),`<button class="button" data-action="export" data-module="${esc(moduleId)}">${icon('download',16)} CSV</button>`)}<div class="view-tabs"><a class="${view==='table'?'active':''}" href="#/explore?view=table&kind=${encodeURIComponent(kind)}&module=${encodeURIComponent(moduleId)}">${icon('list',17)} ${tr('Tabla','Table')}</a><a class="${view==='chart'?'active':''}" href="#/explore?view=chart&kind=${encodeURIComponent(kind)}&module=${encodeURIComponent(moduleId)}">${icon('chart',17)} ${tr('Gráfica','Chart')}</a><a class="${view==='gallery'?'active':''}" href="#/explore?view=gallery">${icon('grid',17)} ${tr('Galería','Gallery')}</a><a class="${view==='map'?'active':''}" href="#/explore?view=map">${icon('map',17)} ${tr('Mapa','Map')}</a></div>${['table','chart'].includes(view)?`<form id="report-filter" class="filter-bar"><label>${tr('Informe','Report')}<select name="kind">${[['overview',tr('Resumen de hojas','Source overview')],['stages',tr('Clutches y estadios','Clutches and stages')],['crosses',tr('Cruces','Crosses')],['samples',tr('Muestras','Samples')],['quality',tr('Calidad de datos','Data quality')],['daily',tr('Por día de origen','By source day')],['weekly',tr('Por semana de origen','By source week')],['counts',tr('Conteos por especie','Counts by species')]].map(([k,label])=>`<option value="${k}" ${k===kind?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>${tr('Hoja','Sheet')}<select name="module"><option value="">${tr('Predeterminada','Default')}</option>${(state.bootstrap?.modules||[]).map(item=>`<option value="${esc(item.id)}" ${item.id===moduleId?'selected':''}>${esc(moduleName(item))}</option>`).join('')}</select></label><button class="button" type="submit">${tr('Aplicar','Apply')}</button></form>`:''}<section class="report-surface">${body}</section>`}
async function galleryView(){const data=await request('/api/records?sheet=Photo_links&limit=80');const records=data.records||[];if(!records.length)return empty('No hay fotos enlazadas en la hoja.');return `<div class="gallery-grid">${records.map(r=>{const vals=r.values||{};const link=Object.entries(vals).find(([k,v])=>/url|link|photo|image|foto/i.test(k)&&safeHref(v))?.[1];const href=safeHref(link);return `<a class="gallery-item" href="#/record/${encodeURIComponent(r.id)}">${href?`<img src="${esc(href)}" alt="Foto asociada a ${esc(recordTitle(r))}" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="gallery-fallback" hidden>${icon('camera',28)}</span>`:`<span class="gallery-fallback">${icon('camera',28)}</span>`}<strong>${esc(recordTitle(r))}</strong><small>${esc(r.sheet)} · ${esc(r.row||'')}</small>${href?`<small class="gallery-original">${tr('Abrir registro para ver el enlace original','Open record for original link')}</small>`:''}</a>`}).join('')}</div><p class="footnote">${tr('Las imágenes se muestran solo cuando la hoja contiene un enlace accesible. Abre el registro para confirmar su identidad.','Images appear only when the sheet has an accessible link. Open the record to confirm identity.')}</p>`}
async function mapView(){const data=await request('/api/records?sheet=Location_data&limit=500');const records=(data.records||[]).map(r=>{const v=r.values||{};const lat=Number(Object.entries(v).find(([k])=>/latitude|latitud|^lat$/i.test(k))?.[1]);const lon=Number(Object.entries(v).find(([k])=>/longitude|longitud|^lon$|^lng$/i.test(k))?.[1]);return {r,lat,lon}}).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180&&!(p.lat===0&&p.lon===0));if(!records.length)return empty('No hay coordenadas verificables en Location_data.');const latMin=Math.min(...records.map(p=>p.lat)),latMax=Math.max(...records.map(p=>p.lat)),lonMin=Math.min(...records.map(p=>p.lon)),lonMax=Math.max(...records.map(p=>p.lon));const pad=v=>Math.max(v,0.05);const plot=records.map(({r,lat,lon})=>{const x=45+(lon-lonMin)/pad(lonMax-lonMin)*610;const y=315-(lat-latMin)/pad(latMax-latMin)*275;return `<a href="#/record/${encodeURIComponent(r.id)}"><circle cx="${x}" cy="${y}" r="5" fill="#b37928" stroke="#fff" stroke-width="2"><title>${esc(recordTitle(r))}: ${lat}, ${lon}</title></circle></a>`}).join('');return `<div class="coordinate-map"><svg viewBox="0 0 700 370" role="img" aria-label="Ubicaciones según latitud y longitud"><rect x="45" y="40" width="610" height="275" fill="#f0f3ea"/><path d="M45 40v275h610" stroke="#8ca99c" fill="none"/>${[1,2,3].map(i=>`<path d="M${45+i*152.5} 40v275M45 ${40+i*68.75}h610" stroke="#d6e0d4"/>`).join('')}${plot}<text x="350" y="350" text-anchor="middle" font-size="13" fill="#375548">Longitud ${esc(lonMin.toFixed(3))} a ${esc(lonMax.toFixed(3))}</text><text x="4" y="32" font-size="13" fill="#375548">Latitud ${esc(latMin.toFixed(3))} a ${esc(latMax.toFixed(3))}</text></svg></div><p class="footnote">${tr('Gráfico local de coordenadas, sin enviar ubicaciones a un mapa externo. Selecciona un punto para revisar su fuente.','Local coordinate plot. Locations are not sent to an external map. Select a point to review its source.')}</p>`}
async function historyPage(query){const recordId=query.get('recordId')||'';const source=query.get('source')||'';const q=query.get('q')||'';const data=await request(`/api/history?limit=60${recordId?`&recordId=${encodeURIComponent(recordId)}`:''}${source?`&source=${encodeURIComponent(source)}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`);const actions=data.actions||[];return `${pageHead(t('history'),tr('Cambios de la aplicación y observaciones de la hoja, con su nivel de evidencia.','App changes and observed sheet edits, with their evidence level.'),`<button class="button button-primary" id="preview-undo" data-action="preview-undo" ${actions.length?'':'disabled'}>${icon('clock',16)} ${tr('Revisar selección','Review selection')}</button>`)}<form id="history-filter" class="filter-bar"><label>${tr('Buscar','Search')}<input name="q" value="${esc(q)}" placeholder="ID, campo o editor"></label><label>${tr('Origen','Source')}<select name="source"><option value="">Todos</option><option value="app" ${source==='app'?'selected':''}>Aplicación</option><option value="external" ${source==='external'?'selected':''}>Hoja externa</option><option value="ai" ${source==='ai'?'selected':''}>Asistente</option></select></label><input name="recordId" type="hidden" value="${esc(recordId)}"><button class="button" type="submit">${tr('Filtrar','Filter')}</button></form>${actions.length?`<div class="history-list">${actions.map(action=>`<article class="history-action"><div class="history-top"><label class="select-action"><input type="checkbox" name="history-select" value="${esc(action.id)}"><span><strong>${esc(action.reason||action.changes?.map(c=>titleCase(c.field)).slice(0,2).join(', ')||'Cambio registrado')}</strong><small>${esc(actorText(action))} · ${esc(fmtTime(action.createdAt))} · ${esc(action.source||'app')}</small></span></label>${pill(action.status)}</div><details><summary>${tr('Ver cambios','View changes')} (${action.changes?.length||0})</summary><div class="changes-table">${(action.changes||[]).map(change=>`<label class="change-row"><input type="checkbox" name="change-select" data-action-id="${esc(action.id)}" value="${esc(change.id)}"><span class="change-field">${esc(titleCase(change.field))}</span><span class="change-before">${esc(objectText(change.before))}</span>${icon('chevron',14)}<span class="change-after">${esc(objectText(change.after))}</span></label>`).join('')}</div></details></article>`).join('')}</div>`:empty('No hay cambios para estos filtros.')}<div id="undo-preview"></div>`}
function chatMessage(message){const role=message.role||message.sender||'assistant';const text=message.content||message.text||message.message||'';return `<div class="chat-message ${role==='user'?'user':'assistant'}"><span class="chat-avatar">${icon(role==='user'?'eye':'spark',17)}</span><div><small>${role==='user'?tr('Tú','You'):tr('Asistente','Assistant')}</small><p>${esc(text)}</p>${message.createdAt?`<time>${esc(fmtTime(message.createdAt))}</time>`:''}</div></div>`}
function sourceRows(sources){if(!sources?.length)return '';return `<div class="answer-sources"><h3>${tr('Fuentes de la respuesta','Answer sources')}</h3>${sources.map(s=>{const href=safeHref(s.sourceUrl||s.url);return `<div>${icon('link',15)}${href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(s.label||s.sheet||s.title||'Fuente')}</a>`:`<span>${esc(s.label||s.sheet||s.title||JSON.stringify(s))}</span>`}${s.row?`<small>fila ${esc(s.row)}</small>`:''}</div>`}).join('')}</div>`}
function resultsView(results){if(!results?.length)return '';return `<div class="answer-results"><h3>${tr('Resultados','Results')}</h3>${results.map(result=>{if(result?.columns&&result?.rows)return reportTable(result);if(result?.series)return chartSvg(result.series);return `<pre>${esc(JSON.stringify(result,null,2))}</pre>`}).join('')}</div>`}
function proposalRows(proposals){if(!proposals?.length)return '';return `<div class="answer-proposals"><h3>${tr('Cambios propuestos','Proposed changes')}</h3><p>${tr('Revisa cada campo y confirma la acción antes de enviarla.','Review each field and confirm the action before sending it.')}</p>${proposals.map(p=>`<div class="proposal"><strong>${esc(p.title||p.reason||'Cambio propuesto')}</strong><pre>${esc(JSON.stringify(p.changes||p.values||p,null,2))}</pre><button class="button button-primary button-small" data-action="apply-proposal" data-id="${esc(p.id)}">${tr('Aplicar cambio revisado','Apply reviewed change')}</button></div>`).join('')}</div>`}
async function assistantPage(threadId){let threads=[],thread=null,error='';try{const data=await request('/api/chat/threads');threads=data.threads||[];if(threadId){const detail=await request(`/api/chat/threads/${encodeURIComponent(threadId)}`);thread=detail.thread||detail}}catch(e){error=e.message}const messages=thread?.messages||[];return `${pageHead(t('assistant'),tr('Pregunta por los registros y revisa cada fuente antes de actuar.','Ask about records and review every source before acting.'),`<button class="button" data-action="new-thread">${icon('plus',17)} ${tr('Nueva conversación','New conversation')}</button>`)}${error?errorBox(error):''}<div class="assistant-layout"><aside class="thread-sidebar"><h2>${tr('Conversaciones','Conversations')}</h2>${threads.length?threads.map(item=>`<a class="thread-link ${String(item.id)===String(threadId)?'active':''}" href="#/assistant/${encodeURIComponent(item.id)}">${icon('spark',16)}<span>${esc(item.title||fmtDate(item.createdAt)||'Conversación')}</span></a>`).join(''):'<p class="muted">No hay conversaciones todavía.</p>'}<div class="knowledge-link"><button class="link-button" data-action="search-knowledge">${icon('book',16)} ${tr('Buscar protocolos','Search protocols')}</button></div></aside><section class="chat-stage">${thread?`<div class="chat-stream" id="chat-stream">${messages.map(chatMessage).join('')}${sourceRows(thread.sources)}${resultsView(thread.results)}${proposalRows(thread.proposals)}</div>`:`<div class="chat-empty"><span class="chat-empty-icon">${icon('spark',31)}</span><h2>${tr('Pregúntale al cuaderno','Ask the workbook')}</h2><p>${tr('Busca registros, compara observaciones o prepara una corrección para revisión. Las respuestas muestran sus fuentes cuando están disponibles.','Find records, compare observations, or draft a correction for review. Answers show their sources when available.')}</p><div class="prompt-examples"><button data-action="chat-prompt" data-prompt="¿Qué cruces F1 carecen de padres preservados?">¿Qué cruces F1 carecen de padres preservados?</button><button data-action="chat-prompt" data-prompt="Muestra los últimos conteos del clutch 944 con sus fuentes">Muestra los últimos conteos del clutch 944</button></div></div>`}<form id="chat-form" class="chat-composer" data-thread="${esc(threadId||'')}"><label class="sr-only" for="chat-input">Mensaje</label><textarea id="chat-input" name="message" rows="2" placeholder="${tr('Pregunta por un individuo, muestra o tarea…','Ask about an individual, sample or task…')}" required></textarea><div class="composer-tools"><div><button type="button" class="icon-button" data-action="chat-photo" title="Extraer borrador de una foto" aria-label="Extraer borrador de una foto">${icon('camera',19)}</button><button type="button" class="icon-button" data-action="chat-voice" title="Transcribir audio" aria-label="Transcribir audio">${icon('mic',19)}</button><input type="file" id="chat-photo-input" accept="image/*" capture="environment" hidden><input type="file" id="chat-voice-input" accept="audio/*" capture hidden></div><button class="button button-primary" type="submit">${tr('Enviar','Send')} ${icon('send',16)}</button></div></form></section></div>`}
async function settingsPage(section){const syncResult=await Promise.allSettled([request('/api/sync')]);const sync=syncResult[0].status==='fulfilled'?syncResult[0].value:null;const outbox=getOutbox(),drafts=listDrafts();let admin='',users=[];if(state.user?.role==='admin'||state.user?.role==='administrator'){try{const [statusResult,userResult]=await Promise.all([request('/api/admin/status'),request('/api/admin/users')]);admin=`<section class="setting-section"><h2>${tr('Administración','Administration')}</h2><dl class="compact-dl">${Object.entries(statusResult||{}).filter(([,v])=>typeof v!=='object').map(([key,value])=>`<div><dt>${esc(titleCase(key))}</dt><dd>${esc(objectText(value))}</dd></div>`).join('')}</dl><div class="setting-actions"><button class="button" data-action="admin-backup">${icon('download',16)} ${tr('Crear copia de seguridad','Create backup')}</button></div></section>`;users=userResult.users||[];state.adminUsers=users}catch(e){admin=errorBox(e)}}return `${pageHead(t('settings'),tr('Cuenta, sincronización y trabajo guardado en este dispositivo.','Account, sync and work stored on this device.'))}<div class="settings-layout"><div><section class="setting-section"><h2>${tr('Cuenta','Account')}</h2><dl class="compact-dl"><div><dt>Usuario</dt><dd>${esc(state.user?.displayName||state.user?.username)}</dd></div><div><dt>Rol</dt><dd>${esc(state.user?.role||'')}</dd></div><div><dt>${tr('Entorno','Environment')}</dt><dd>${esc(currentLabel())}</dd></div></dl><div class="language-setting"><span>${tr('Idioma','Language')}</span><div class="segmented"><button data-action="language" data-lang="es" ${state.lang==='es'?'aria-pressed="true"':''}>Español</button><button data-action="language" data-lang="en" ${state.lang==='en'?'aria-pressed="true"':''}>English</button></div></div></section><section class="setting-section"><div class="section-head"><h2>${tr('Sincronización','Sync')}</h2>${pill(sync?.status||'pending')}</div><p>${sync?.lastSyncAt?`Última revisión: ${esc(fmtTime(sync.lastSyncAt))}`:tr('Aún no se informa una última sincronización.','No last sync reported.')}</p><button class="button" data-action="sync-now">${icon('sync',17)} ${tr('Revisar hoja ahora','Check sheet now')}</button></section><section class="setting-section"><h2>${tr('Pendientes en este dispositivo','Pending on this device')} <span class="count-label">${outbox.length}</span></h2>${outbox.length?`<div class="outbox-list">${outbox.map(item=>`<div class="outbox-item"><div><strong>${esc(item.path)}</strong><small>${esc(fmtTime(item.createdAt))} · ${esc(item.status)}</small>${item.error?`<p>${esc(item.error)}</p>`:''}</div>${item.status==='conflict'?`<button class="button button-small" data-action="retry-outbox-item" data-id="${esc(item.id)}">${tr('Revisar y reintentar','Review and retry')}</button>`:''}<button class="button button-small" data-action="discard-outbox" data-id="${esc(item.id)}">${tr('Descartar','Discard')}</button></div>`).join('')}</div><button class="button button-primary" data-action="retry-outbox">${icon('sync',17)} ${tr('Reintentar pendientes','Retry pending')}</button>`:'<p class="muted">No hay envíos pendientes.</p>'}${drafts.length?`<p class="footnote">${drafts.length} ${tr('borradores locales guardados','local drafts saved')}.</p>`:''}</section>${admin}</div><aside><div class="side-panel"><h2>${tr('Fuente de datos','Data source')}</h2><p>${tr('Esta aplicación escribe en la copia personal de prueba. El libro de producción no es el destino de guardado.','This app writes to the personal test copy. The production workbook is not the save destination.')}</p>${safeHref(state.bootstrap?.settings?.sheetUrl)?`<a href="${esc(safeHref(state.bootstrap.settings.sheetUrl))}" target="_blank" rel="noopener noreferrer">${tr('Abrir hoja de prueba','Open test sheet')} ${icon('link',15)}</a>`:''}</div>${users.length?`<div class="side-panel"><h2>${tr('Usuarios','Users')}</h2>${users.map(u=>`<div class="user-row"><strong>${esc(u.displayName||u.username)}</strong><small>${esc(u.role||'')} · ${u.active?tr('Activo','Active'):tr('Inactivo','Inactive')}</small><button class="link-button" data-action="edit-user" data-id="${esc(u.id)}">${tr('Gestionar','Manage')}</button></div>`).join('')}<button class="button button-small" data-action="show-user-form">${icon('plus',15)} ${tr('Añadir usuario','Add user')}</button><form id="user-form" class="stack-form hidden"><label>${tr('Usuario','Username')}<input name="username" required></label><label>Nombre<input name="displayName" required></label><label>${tr('Contraseña','Password')}<input name="password" type="password" required minlength="6" maxlength="16" autocomplete="new-password"></label><label>Rol<select name="role"><option value="observer">Observador</option><option value="editor">Editor</option><option value="reviewer">Revisor</option><option value="admin">Administrador</option></select></label><button class="button button-primary" type="submit">${tr('Crear usuario','Create user')}</button></form></div>`:''}</aside></div>`}
async function importPage(moduleId){const m=mod(moduleId);if(!m)return empty('No se encontró esta hoja.');return `<div class="breadcrumb"><a href="#/module/${encodeURIComponent(m.id)}">${esc(moduleName(m))}</a>${icon('chevron',14)}<span>Importar CSV</span></div>${pageHead(`Importar CSV · ${moduleName(m)}`,tr('Previsualiza errores y duplicados antes de aplicar filas.','Preview errors and duplicates before applying rows.'))}<div class="import-layout"><form id="import-form" data-module="${esc(m.id)}" class="editor-form"><div class="field"><label for="csv-file">Archivo CSV</label><input id="csv-file" type="file" accept=".csv,text/csv" required></div><p>${tr('Los encabezados deben coincidir con los campos de la hoja. Nada se guarda durante la vista previa.','Headers must match sheet fields. Preview does not save anything.')}</p><button class="button button-primary" type="submit">${icon('eye',16)} ${tr('Vista previa','Preview')}</button></form><div id="import-preview"></div></div>`}
function modal(title,body,buttons=''){const existing=document.getElementById('dialog');existing?.remove();const dialog=document.createElement('dialog');dialog.id='dialog';dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Cerrar">${icon('close',18)}</button></div><div class="dialog-body">${body}</div>${buttons?`<div class="dialog-actions">${buttons}</div>`:''}`;document.body.append(dialog);dialog.showModal();return dialog}
function updateFormState(text,status='pending'){const el=document.getElementById('form-state');if(el)el.innerHTML=`${icon(status==='saved'?'check':'clock',16)} ${esc(text)}`}
function dateToday(){return new Date().toLocaleDateString('en-CA',{timeZone:'America/Guayaquil'})}
async function handleAction(button,event){const action=button.dataset.action;switch(action){
case 'dismiss-notice':state.notice=null;renderNotice();break;
case 'toggle-menu':state.mobileMenu=!state.mobileMenu;document.getElementById('mobile-menu')?.classList.toggle('open',state.mobileMenu);break;
case 'search-focus':modal(tr('Buscar en todos los registros','Search all records'),`<form id="global-search" class="inline-search">${icon('search',19)}<input name="q" placeholder="${esc(t('search'))}" autofocus required><button class="button button-primary" type="submit">${tr('Buscar','Search')}</button></form><p class="footnote">${tr('Una marca puede corresponder a más de una fila. Comprueba los detalles antes de actuar.','A mark can match more than one row. Check details before acting.')}</p>`);document.querySelector('#global-search input')?.focus();break;
case 'mobile-search':{const q=document.getElementById('mobile-global-search')?.value?.trim();if(q)route(`/register?q=${encodeURIComponent(q)}`);break}
case 'show-outbox':route('/settings');break;
case 'save-record-draft':{const form=document.getElementById('record-form');if(!form)break;const raw={};for(const field of mod(form.dataset.module)?.fields||[]){const key=field.key||field.name;const input=Array.from(form.elements).find(el=>el.name===key);if(input&&!input.readOnly&&!input.disabled)raw[key]=input.type==='checkbox'?input.checked:input.value}saveDraft(`record:${form.dataset.module}:${form.dataset.record}`,raw);updateFormState(tr('Borrador guardado en este dispositivo','Draft saved on this device'));notify(tr('Borrador guardado.','Draft saved.'));break}
case 'retry-emergence':if(state.emergenceRetry){document.getElementById('dialog')?.remove();await submitEmergenceBatch(state.emergenceRetry)}break;
case 'new-record':modal(t('new'),`<div class="picker-list">${(state.bootstrap?.modules||[]).map(m=>`<a href="#/form/${encodeURIComponent(m.id)}/new">${esc(moduleName(m))}<small>${esc(m.sheet)}</small>${icon('chevron',15)}</a>`).join('')}</div>`);break;
case 'close-dialog':document.getElementById('dialog')?.close();document.getElementById('dialog')?.remove();break;
case 'refresh':renderRoute();break;
case 'language':if(state.setupRequired&&!state.setupTokenFromLink)state.setupToken=document.getElementById('setup-token')?.value??state.setupToken;state.lang=button.dataset.lang;localStorage.setItem('ithomiini.lang',state.lang);document.documentElement.lang=state.lang;document.getElementById('dialog')?.remove();if(state.user)renderRoute();else renderAuth(state.setupRequired);break;
case 'logout':if(state.offlineResume||!navigator.onLine)localStorage.setItem('ithomiini.pendingLogout.v1','1');else await request('/api/auth/logout',{method:'POST'});clearOfflineResume();state.user=null;state.bootstrap=null;state.offlineResume=false;setCsrf('');setUserScope(null);renderAuth();break;
case 'complete-task':await request(`/api/tasks/${encodeURIComponent(button.dataset.id)}`,{method:'PATCH',body:{status:'done'},queue:true});notify('Tarea completada.');renderRoute();break;
case 'show-task-form':document.getElementById('task-form')?.classList.remove('hidden');document.getElementById('task-title')?.focus();break;
case 'show-user-form':document.getElementById('user-form')?.classList.remove('hidden');break;
case 'edit-user':{const user=state.adminUsers?.find(item=>String(item.id)===button.dataset.id);if(!user)return;modal(tr('Gestionar usuario','Manage user'),`<form id="user-edit-form" class="stack-form" data-id="${esc(user.id)}"><label>${tr('Nombre visible','Display name')}<input name="displayName" value="${esc(user.displayName||'')}" required></label><label>${tr('Rol','Role')}<select name="role">${['observer','editor','reviewer','admin'].map(role=>`<option value="${role}" ${user.role===role?'selected':''}>${role}</option>`).join('')}</select></label><label class="checkbox-label"><input name="active" type="checkbox" ${user.active?'checked':''} ${user.id===state.user.id?'disabled':''}> ${tr('Cuenta activa','Active account')}</label><label>${tr('Nueva contraseña, si quieres restablecerla','New password, if resetting')}<input name="password" type="password" minlength="6" maxlength="16" autocomplete="new-password"></label><button type="submit" class="button button-primary">${tr('Guardar cambios','Save changes')}</button></form>`);break}
case 'export':await download(`/api/export?format=csv${button.dataset.module?`&module=${encodeURIComponent(button.dataset.module)}`:''}`,`ithomiini-${button.dataset.module||'records'}.csv`);break;
case 'scan':await startScan();break;
case 'print-label':printLabel(state.record);break;
case 'attach-file':document.getElementById('attachment-input')?.click();break;
case 'sync-now':{const result=await request('/api/sync',{method:'POST',body:{}});notify(result.status==='verified'?'Hoja revisada.':'Revisión iniciada.');renderRoute();break}
case 'retry-outbox':await flushOutbox(({status,error})=>{if(status==='conflict')notify(error.message,'error')});notify('Se revisaron los envíos pendientes.');renderRoute();break;
case 'retry-outbox-item':{const item=getOutbox().find(i=>i.id===button.dataset.id);if(!item)break;modal(tr('Revisar envío pendiente','Review pending send'),`<p>${tr('Comprueba el contenido y el error antes de reintentar. Se usa el mismo ID de solicitud.','Check the content and error before retrying. The same request ID will be used.')}</p><pre>${esc(JSON.stringify(item.body,null,2))}</pre>${item.error?`<div class="message error">${esc(item.error)}</div>`:''}${item.details?`<pre>${esc(JSON.stringify(item.details,null,2))}</pre>`:''}`,`<button class="button" data-action="close-dialog">${t('cancel')}</button><button class="button button-primary" data-action="confirm-retry-outbox-item" data-id="${esc(item.id)}">${tr('Reintentar','Retry')}</button>`);break}
case 'confirm-retry-outbox-item':{const item=getOutbox().find(i=>i.id===button.dataset.id);if(!item)break;const result=await request(item.path,{method:item.method,body:item.body});discardQueued(item.id);document.getElementById('dialog')?.remove();notify(statusLabel(result.status||'saved'));renderRoute();break}
case 'discard-outbox':{const item=getOutbox().find(i=>i.id===button.dataset.id);modal('Descartar envío pendiente',`<p>${tr('Esta acción quita el envío de este dispositivo. Conserva los datos antes de descartarlo.','This removes the pending send from this device. Keep the data elsewhere before discarding it.')}</p><pre>${esc(JSON.stringify(item?.body?.values||item?.body||{},null,2))}</pre>`,`<button class="button" data-action="close-dialog">${t('cancel')}</button><button class="button button-danger" data-action="confirm-discard" data-id="${esc(button.dataset.id)}">${tr('Descartar','Discard')}</button>`);break}
case 'confirm-discard':discardQueued(button.dataset.id);document.getElementById('dialog')?.remove();renderRoute();break;
case 'admin-backup':{const data=await request('/api/admin/backup',{method:'POST',body:{}});notify(data.message||'Copia de seguridad creada.');break}
case 'new-thread':{const data=await request('/api/chat/threads',{method:'POST',body:{}});const thread=data.thread||data;route(`/assistant/${encodeURIComponent(thread.id)}`);break}
case 'chat-prompt':{let id=state.params.parts[1];if(!id){const data=await request('/api/chat/threads',{method:'POST',body:{}});id=(data.thread||data).id}route(`/assistant/${encodeURIComponent(id)}`);sessionStorage.setItem('ithomiini.pendingPrompt',button.dataset.prompt);break}
case 'apply-proposal':modal('Aplicar cambio del asistente',`<p>Confirma que revisaste la propuesta y sus fuentes. El sistema registrará esta acción en el historial.</p><label>Motivo de aplicación<input id="proposal-reason" value="Propuesta revisada" required></label>`,`<button class="button" data-action="close-dialog">${t('cancel')}</button><button class="button button-primary" data-action="confirm-proposal" data-id="${esc(button.dataset.id)}">${tr('Confirmar aplicación','Confirm apply')}</button>`);break;
case 'confirm-proposal':{const reason=document.getElementById('proposal-reason')?.value?.trim();if(!reason){document.getElementById('proposal-reason')?.focus();break}const result=await request(`/api/chat/proposals/${encodeURIComponent(button.dataset.id)}/apply`,{method:'POST',body:{reason}});document.getElementById('dialog')?.remove();notify(statusLabel(result.status||'pending'));renderRoute();break}
case 'chat-photo':document.getElementById('chat-photo-input')?.click();break;
case 'chat-voice':document.getElementById('chat-voice-input')?.click();break;
case 'search-knowledge':modal(tr('Buscar protocolos','Search protocols'),`<form id="knowledge-search" class="inline-search">${icon('search',18)}<input name="q" required placeholder="Protocolo, método o palabra"><button class="button button-primary" type="submit">Buscar</button></form><div id="knowledge-results"></div>`);break;
case 'preview-undo':await previewUndo();break;
case 'confirm-undo':await confirmUndo();break;
case 'apply-import':await applyImport(button.dataset.preview);break;
} }
async function startScan(){if(!('BarcodeDetector'in window)){modal('Escanear etiqueta',`<p>${tr('Este navegador no ofrece escaneo integrado. Escribe la marca o el ID para buscarlo.','This browser has no built-in scanner. Enter the mark or ID to search.')}</p><form id="global-search" class="inline-search"><input name="q" required placeholder="Marca, CAM o tubo"><button class="button button-primary" type="submit">Buscar</button></form>`);return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const detector=new BarcodeDetector({formats:['qr_code','code_128','data_matrix']});const dialog=modal('Escanear etiqueta',`<video id="scan-video" autoplay playsinline muted></video><p>Apunta a un QR o código de barras. También puedes buscarlo manualmente.</p><form id="global-search" class="inline-search"><input name="q" required placeholder="Marca, CAM o tubo"><button class="button button-primary" type="submit">Buscar</button></form>`);const video=dialog.querySelector('video');video.srcObject=stream;let active=true;dialog.addEventListener('close',()=>{active=false;stream.getTracks().forEach(track=>track.stop())});const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes.length){const raw=codes[0].rawValue;dialog.close();dialog.remove();stream.getTracks().forEach(track=>track.stop());if(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(raw))route(`/record/${encodeURIComponent(raw)}`);else route(`/register?q=${encodeURIComponent(raw)}`);return}}catch{}requestAnimationFrame(scan)};scan()}catch(error){stream?.getTracks().forEach(track=>track.stop());modal('Escanear etiqueta',`<p>${esc(error.message||'No se pudo abrir la cámara.')}</p><form id="global-search" class="inline-search"><input name="q" required placeholder="Marca, CAM o tubo"><button class="button button-primary" type="submit">Buscar</button></form>`)}}
function printLabel(record){if(!record)return;const w=window.open('','_blank','width=650,height=450');if(!w){notify('Permite ventanas emergentes para imprimir la etiqueta.','error');return}const label=recordTitle(record,moduleForSheet(record.sheet));const barcode=code128Svg(String(record.id));w.document.write(`<!doctype html><html><head><title>Etiqueta ${esc(label)}</title><style>@page{size:110mm 60mm;margin:5mm}body{font:13px Arial,sans-serif;margin:12px;color:#173c34}.label{border:1px solid #173c34;padding:12px;width:100mm;max-width:100%;box-sizing:border-box}.brand{font-size:11px;text-transform:uppercase;letter-spacing:.15em}.id{font-size:23px;font-weight:bold;margin:9px 0;overflow-wrap:anywhere}.meta{font-size:10px;line-height:1.5}.barcode{margin-top:8px}.app-id{font:9px monospace;overflow-wrap:anywhere;text-align:center;margin-top:3px}@media print{body{margin:0}.label{border:1px solid #333;break-inside:avoid}}</style></head><body><div class="label"><div class="brand">Ithomiini</div><div class="id">${esc(label)}</div><div class="meta">${esc(record.sheet||'')} · ${esc(record.row||'')}</div><div class="barcode">${barcode}</div><div class="app-id">${esc(record.id||'')}</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function selectedHistory(){const selectedActions=[...document.querySelectorAll('input[name="history-select"]:checked')].map(el=>el.value);const checkedChanges=[...document.querySelectorAll('input[name="change-select"]:checked')];const actionIds=[...new Set([...selectedActions,...checkedChanges.map(el=>el.dataset.actionId)])];const changeIds=checkedChanges.map(el=>el.value);return {actionIds,changeIds:changeIds.length?changeIds:undefined}}
async function previewUndo(){const selected=selectedHistory();if(!selected.actionIds.length){notify('Selecciona al menos una acción.','error');return}const result=await request('/api/history/preview',{method:'POST',body:selected});const host=document.getElementById('undo-preview');host.innerHTML=`<div class="preview-panel"><h2>${tr('Vista previa de reversión','Reversal preview')}</h2>${result.conflicts?.length?`<div class="message error">${icon('alert',17)} ${result.conflicts.length} ${tr('conflictos requieren revisión','conflicts need review')}</div><pre>${esc(JSON.stringify(result.conflicts,null,2))}</pre>`:''}<div class="changes-table">${(result.changes||[]).map(c=>`<div class="change-row"><span class="change-field">${esc(titleCase(c.field))}</span><span>${esc(objectText(c.before))}</span>${icon('chevron',15)}<span>${esc(objectText(c.after))}</span></div>`).join('')}</div>${result.eligible?`<label class="field">Motivo de la reversión<input id="undo-reason" required placeholder="Explica la corrección"></label><button class="button button-primary" data-action="confirm-undo">${tr('Aplicar reversión revisada','Apply reviewed reversal')}</button>`:`<p class="muted">${tr('No hay cambios elegibles para revertir automáticamente.','No changes are eligible for automatic reversal.')}</p>`}</div>`;host.scrollIntoView({behavior:'smooth',block:'start'})}
async function confirmUndo(){const reason=document.getElementById('undo-reason')?.value?.trim();if(!reason){document.getElementById('undo-reason')?.focus();notify('Explica el motivo de la reversión.','error');return}const result=await request('/api/history/undo',{method:'POST',body:{...selectedHistory(),reason}});notify(statusLabel(result.status||'pending'));renderRoute()}
async function applyImport(previewId){const result=await request('/api/import/apply',{method:'POST',body:{previewId}});notify(statusLabel(result.status||'pending'));route(`/module/${encodeURIComponent(state.params.parts[1])}`)}
function coreWorkflowPage(w){const id=w.id;state.quickRecord=null;if(id==='capture')state.captureSource=null;const m=moduleForSheet(w.sheet);const head=`<div class="breadcrumb"><a href="#/workflows">${t('workflows')}</a>${icon('chevron',14)}<span>${esc(tr(w.title,w.en))}</span></div>${pageHead(tr(w.title,w.en),workflowSummary(w),m?`<a class="button" href="#/module/${encodeURIComponent(m.id)}">${icon('book',16)} ${tr('Abrir hoja','Open sheet')}</a>`:'')}`;
  if(id==='death'||id==='preserve')return `${head}<div class="editor-layout"><form id="core-status-form" class="editor-form" data-kind="${esc(id)}"><div class="form-banner">${icon('book',17)}<span>${tr('Actualiza el registro de la hoja','Update the sheet record')} · ${esc(currentLabel())}</span></div><div class="form-section-heading"><h2>${tr('Seleccionar individuo','Select individual')}</h2><p>${tr('Busca por marca o ID y elige la fila exacta. La misma marca puede aparecer varias veces.','Search by mark or ID and choose the exact row. The same mark may appear more than once.')}</p></div><div class="field"><label for="core-record-search">Marca, CAM o ID</label><input id="core-record-search" type="search" autocomplete="off" data-autofocus placeholder="A0A, CAM, marca…"></div><div id="core-search-results" class="candidate-list"></div><input type="hidden" name="recordId" id="core-record-id" required><div id="core-selected"></div><div class="fields-grid">${id==='death'?`<div class="field"><label for="core-date">${tr('Fecha de muerte observada','Observed death date')}</label><input id="core-date" name="date" type="date" required value="${dateToday()}"></div><div class="field"><label for="core-cause">${tr('Causa','Cause')}</label><input id="core-cause" name="cause" placeholder="${tr('Si se conoce','If known')}"></div><div class="field span-full"><label for="core-evidence">${tr('Evidencia o motivo de corrección','Evidence or correction reason')}</label><textarea id="core-evidence" name="reason" rows="3" required></textarea></div>`:`<div class="field"><label for="core-date">${tr('Fecha de preservación','Preservation date')}</label><input id="core-date" name="date" type="date" required value="${dateToday()}"></div><div class="field"><label for="core-medium">${tr('Medio','Medium')}</label><input id="core-medium" name="medium" required></div><div class="field"><label for="core-condition">${tr('Condición al preservar','Condition at preservation')}</label><select id="core-condition" name="condition"><option value="">${tr('Sin registrar','Unrecorded')}</option><option value="Dead">Dead</option><option value="Alive">Alive</option></select></div><div class="field span-full"><label for="core-evidence">${tr('Evidencia o motivo de corrección','Evidence or correction reason')}</label><textarea id="core-evidence" name="reason" rows="3" required></textarea></div>`}</div><div class="form-footer"><span class="form-state" id="form-state">${tr('Selecciona un individuo para continuar','Select an individual to continue')}</span><button class="button button-primary" type="submit">${icon('check',17)} ${tr('Guardar en la hoja','Save to sheet')}</button></div></form><aside class="editor-side"><div class="side-panel"><h2>${tr('Datos de origen','Source data')}</h2><p>${tr('La aplicación revisa la versión actual y conserva las fórmulas. Si el campo procede de Insectary_data, el guardado se dirige a esa fuente.','The app checks the current version and preserves formulas. If this field comes from Insectary_data, saving targets that source.')}</p></div></aside></div>`;
  if(id==='capture')return `${head}<div class="editor-layout"><form id="capture-form" class="editor-form"><div class="form-banner">${icon('map',17)}<span>${tr('Nueva fila en Collection_data','New row in Collection_data')} · ${esc(currentLabel())}</span></div><div class="form-section-heading"><h2>${tr('Encuentro de campo','Field encounter')}</h2><p>${tr('Registra la marca, lugar y destino. Para recapturas, verifica los candidatos antes de guardar.','Record mark, place and disposition. For recaptures, verify candidates before saving.')}</p></div><div class="fields-grid"><div class="field"><label for="capture-mark">${tr('Marca de campo','Field mark')}</label><input id="capture-mark" name="FieldMark_ID" required data-autofocus></div><div class="field"><label for="capture-date">${tr('Fecha','Date')}</label><input id="capture-date" name="Collection_date" type="date" value="${dateToday()}" required></div><div class="field"><label for="capture-disposition">${tr('Destino','Disposition')}</label><select id="capture-disposition" name="Release_Collect"><option value="">${tr('Seleccionar','Select')}</option><option value="Released">${tr('Liberado','Released')}</option><option value="Collected">${tr('Colectado','Collected')}</option><option value="Insectary">${tr('Insectario','Insectary')}</option></select></div><div class="field"><label for="capture-location">${tr('Lugar','Location')}</label><input id="capture-location" name="Collection_location"></div><div class="field"><label for="capture-transect">${tr('Transecto','Transect')}</label><input id="capture-transect" name="Transect_section"></div><div class="field"><label for="capture-visit">${tr('ID de visita','Visit ID')}</label><input id="capture-visit" name="visitId" placeholder="${tr('Opcional','Optional')}"></div><div class="field"><label for="capture-time">${tr('Hora','Time')}</label><input id="capture-time" name="Collection_time" type="time"></div><div class="field"><label for="capture-collector">${tr('Colector','Collector')}</label><input id="capture-collector" name="Collector"></div><div class="field"><label for="capture-sex">${tr('Sexo','Sex')}</label><select id="capture-sex" name="Sex"><option value="">${tr('Desconocido','Unknown')}</option><option value="M">M</option><option value="F">F</option></select></div><div class="field span-full"><label for="capture-notes">${tr('Notas','Notes')}</label><textarea id="capture-notes" name="Notes_Collection_data" rows="3"></textarea></div></div><div id="capture-candidates"></div><div class="form-footer"><span class="form-state" id="form-state">${tr('Busca coincidencias de la marca antes de guardar','Check mark matches before saving')}</span><button class="button button-primary" type="submit">${icon('check',17)} ${tr('Guardar captura','Save capture')}</button></div></form><aside class="editor-side"><div class="side-panel"><h2>${tr('Registro completo','Full record')}</h2><p>${tr('Puedes añadir taxonomía, tubos, condiciones y otros campos en el formulario de la hoja.','Add taxonomy, tubes, conditions and other fields in the sheet form.')}</p>${m?`<a href="#/form/${encodeURIComponent(m.id)}/new">${tr('Abrir formulario completo','Open full form')} ${icon('chevron',14)}</a>`:''}</div></aside></div>`;
  return `${head}<div class="editor-layout"><form id="emergence-form" class="editor-form"><div class="form-banner">${icon('layers',17)}<span>${tr('Lote de adultos en Insectary_data','Adult batch in Insectary_data')} · ${esc(currentLabel())}</span></div><div class="form-section-heading"><h2>${tr('Identificar clutch','Identify clutch')}</h2><p>${tr('Los ID de insectario se asignan al guardar. Revisa cada sexo antes de registrar el lote.','Insectary IDs are allocated on save. Review each sex before recording the batch.')}</p></div><div class="fields-grid"><div class="field"><label for="emergence-clutch">${tr('Nº de clutch','Clutch number')}</label><input id="emergence-clutch" name="clutch" required data-autofocus></div><div class="field"><label for="emergence-date">${tr('Fecha de emergencia','Emergence date')}</label><input id="emergence-date" name="date" type="date" required value="${dateToday()}"></div><div class="field"><label for="emergence-species">${tr('Especie de la hoja','Sheet species')}</label><input id="emergence-species" name="species" readonly placeholder="${tr('Se calcula desde el clutch','Calculated from clutch')}"><small class="field-note">${tr('La fórmula de la hoja determina la especie.','The sheet formula determines species.')}</small></div><div class="field"><label for="emergence-count">${tr('Número de adultos','Number of adults')}</label><input id="emergence-count" name="count" type="number" min="1" max="50" value="1" required></div></div><div id="emergence-individuals" class="batch-individuals"></div><div id="emergence-candidates"></div><div class="form-footer"><span class="form-state" id="form-state">${tr('ID nuevos al guardar','New IDs on save')}</span><button class="button button-primary" type="submit">${icon('check',17)} ${tr('Registrar lote','Record batch')}</button></div></form><aside class="editor-side"><div class="side-panel"><h2>${tr('Revisión del lote','Batch review')}</h2><p>${tr('Cada adulto crea una fila individual vinculada al clutch. Usa el registro completo para completar más detalles después.','Each adult creates an individual row linked to the clutch. Use the full record later for more details.')}</p></div></aside></div>`}
function renderBatchIndividuals(){const count=Math.min(50,Math.max(1,Number(document.getElementById('emergence-count')?.value||1)));const host=document.getElementById('emergence-individuals');if(!host)return;host.innerHTML=`<h3>${count} ${count===1?tr('adulto','adult'):tr('adultos','adults')}</h3><div class="batch-grid">${Array.from({length:count},(_,i)=>`<label>${tr('Adulto','Adult')} ${i+1}<select name="sex-${i}"><option value="">${tr('Sexo desconocido','Sex unknown')}</option><option value="M">${tr('Macho','Male')}</option><option value="F">${tr('Hembra','Female')}</option></select></label>`).join('')}</div>`}
async function submitEmergenceBatch(body){state.emergenceRetry=body;try{const result=await request('/api/actions',{method:'POST',body,queue:true});state.emergenceRetry=null;clearDraft('quick:emergence-form:');notify(result.queued?tr('Lote pendiente sin conexión.','Batch pending offline.'):statusLabel(result.status||'saved'));if(result.queued)return;const linked=result.records?.[0]?.id;if(linked)route(`/record/${encodeURIComponent(linked)}`);else route('/workflows')}catch(error){if(error.code!=='PARTIAL_ACTION')throw error;const applied=error.details?.applied||[];modal(tr('Lote guardado parcialmente','Batch partially saved'),`<p>${applied.length} ${tr('adultos ya tienen fila guardada. El siguiente intento usará el mismo ID de solicitud para continuar sin duplicarlos.','adults already have saved rows. Retry uses the same request ID to continue without duplicating them.')}</p><div class="partial-ids">${applied.map(item=>`<a href="#/record/${encodeURIComponent(item.recordId)}">${esc(item.recordId)}</a>`).join('')}</div><p>${tr('Primer adulto pendiente:','First pending adult:')} ${esc(Number(error.details?.failedIndex??0)+1)}</p><p>${esc(error.details?.cause?.message||'')}</p>`,`<button class="button" data-action="close-dialog">${t('cancel')}</button><button class="button button-primary" data-action="retry-emergence">${tr('Reintentar resto del lote','Retry remaining batch')}</button>`);updateFormState(tr('Guardado parcial; revisa los ID','Partially saved; review IDs'),'error')}}
async function handleSubmit(form){const id=form.id;const fields=new FormData(form);if(id==='auth-form'){if(!form.reportValidity())return;const setup=!!form.elements.token;const body=Object.fromEntries(fields);if(setup)state.setupToken=String(body.token||'');localStorage.removeItem('ithomiini.pendingLogout.v1');const data=await request(setup?'/api/auth/setup':'/api/auth/login',{method:'POST',body});setCsrf(data.csrf);state.user=data.user;setUserScope(data.user?.id);if(await loadSession()){state.setupToken='';state.setupTokenFromLink=false;if(getRoute().parts[0]==='setup')route('/daily');else renderRoute()}return}
if(id==='global-search'){const q=String(fields.get('q')||'').trim();document.getElementById('dialog')?.remove();if(q)route(`/register?q=${encodeURIComponent(q)}`);return}
if(id==='register-search'){route(`/register?q=${encodeURIComponent(String(fields.get('q')||'').trim())}`);return}
if(id==='module-search'){route(`/module/${encodeURIComponent(form.dataset.module)}?q=${encodeURIComponent(String(fields.get('q')||'').trim())}`);return}
if(id==='record-form'){if(!form.reportValidity())return;const m=mod(form.dataset.module),editing=form.dataset.record!=='new',original=state.editingRecord?.values||{};const values=formValues(form,m,{onlyChanged:editing,original});if(!Object.keys(values).length){notify(tr('No hay cambios para guardar.','No changes to save.'));return}updateFormState(tr('Guardando…','Saving…'));const path=editing?`/api/records/${encodeURIComponent(form.dataset.record)}`:'/api/records';try{const result=await request(path,{method:editing?'PATCH':'POST',body:{...(editing?{values,expectedVersion:state.editingRecord.version,reason:tr('Edición desde el formulario','Form edit')}:{module:m.id,values})},queue:true});clearDraft(`record:${m.id}:${form.dataset.record}`);notify(result.queued?tr('Guardado en este dispositivo. Envío pendiente.','Saved on this device. Send pending.'):statusLabel(result.status||'saved'));if(result.queued){updateFormState(tr('Pendiente sin conexión','Pending offline'));return}route(`/record/${encodeURIComponent(result.record?.id||form.dataset.record)}`)}catch(error){updateFormState(error.status===409?tr('Conflicto: revisa los cambios recientes','Conflict: review recent changes'):error.message,'error');throw error}return}
if(id==='event-form'){if(!form.reportValidity())return;const kind=form.dataset.kind,values=Object.fromEntries(fields);for(const [key,value] of Object.entries(values)){if(value==='')delete values[key];else if(form.elements.namedItem(key)?.type==='number')values[key]=Number(value)}const recordId=document.getElementById('event-record-id')?.value.trim()||undefined;if(!Object.keys(values).length){notify(tr('Escribe al menos una observación.','Enter at least one observation.'),'error');return}const result=await request('/api/events',{method:'POST',body:{kind,recordId,values},queue:true});clearDraft(`event:${kind}`);notify(result.queued?tr('Observación pendiente sin conexión.','Observation pending offline.'):statusLabel(result.status||'saved'));renderRoute();return}
if(id==='task-form'){if(!form.reportValidity())return;const body=Object.fromEntries(fields);for(const key of Object.keys(body))if(!body[key])delete body[key];body.status='open';const result=await request('/api/tasks',{method:'POST',body,queue:true});notify(result.queued?'Tarea pendiente sin conexión.':'Tarea creada.');renderRoute();return}
if(id==='report-filter'){const kind=fields.get('kind'),module=fields.get('module');route(`/explore?view=${encodeURIComponent(state.params.query.get('view')||'table')}&kind=${encodeURIComponent(kind)}&module=${encodeURIComponent(module)}`);return}
if(id==='history-filter'){const q=fields.get('q'),source=fields.get('source'),recordId=fields.get('recordId');route(`/history?q=${encodeURIComponent(q)}&source=${encodeURIComponent(source)}&recordId=${encodeURIComponent(recordId)}`);return}
if(id==='chat-form'){if(!form.reportValidity())return;const message=String(fields.get('message')||'').trim();if(!message)return;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;submit.innerHTML=`${icon('sync',16)} ${tr('Consultando…','Working…')}`;try{let threadId=form.dataset.thread;if(!threadId){const created=await request('/api/chat/threads',{method:'POST',body:{}});threadId=(created.thread||created).id}await request(`/api/chat/threads/${encodeURIComponent(threadId)}/messages`,{method:'POST',body:{message}});route(`/assistant/${encodeURIComponent(threadId)}`)}finally{submit.disabled=false}return}
if(id==='user-form'){if(!form.reportValidity())return;await request('/api/admin/users',{method:'POST',body:Object.fromEntries(fields)});notify('Usuario creado.');renderRoute();return}
if(id==='user-edit-form'){if(!form.reportValidity())return;const body={displayName:String(fields.get('displayName')||'').trim(),role:String(fields.get('role')||'')};if(form.dataset.id!==state.user.id)body.active=fields.get('active')==='on';if(fields.get('password'))body.password=String(fields.get('password'));await request(`/api/admin/users/${encodeURIComponent(form.dataset.id)}`,{method:'PATCH',body});document.getElementById('dialog')?.remove();if(form.dataset.id===state.user.id&&body.password){state.user=null;state.bootstrap=null;setCsrf('');setUserScope(null);renderAuth(false);notify(tr('Contraseña cambiada. Inicia sesión de nuevo.','Password changed. Sign in again.'));return}notify(tr('Usuario actualizado.','User updated.'));renderRoute();return}
if(id==='knowledge-search'){const q=String(fields.get('q')||'').trim();const data=await request(`/api/knowledge?q=${encodeURIComponent(q)}`);const host=document.getElementById('knowledge-results');host.innerHTML=(data.documents||[]).length?(data.documents||[]).map(doc=>`<button class="knowledge-result" data-action="open-knowledge" data-id="${esc(doc.id)}"><strong>${esc(doc.title||doc.name)}</strong><small>${esc(doc.source||'')}</small></button>`).join(''):empty('No se encontraron documentos.');return}
if(id==='import-form'){const file=document.getElementById('csv-file')?.files?.[0];if(!file)return;const csv=await file.text();const data=await request('/api/import/preview',{method:'POST',body:{module:form.dataset.module,csv}});const host=document.getElementById('import-preview');host.innerHTML=`<section class="preview-panel"><h2>${tr('Vista previa','Preview')} · ${data.rows?.length||0} ${tr('filas','rows')}</h2>${data.errors?.length?`<div class="message error">${data.errors.length} ${tr('errores','errors')}</div><pre>${esc(JSON.stringify(data.errors,null,2))}</pre>`:''}<div class="preview-scroll"><pre>${esc(JSON.stringify((data.rows||[]).slice(0,10),null,2))}</pre></div>${data.previewId&&!(data.errors||[]).length?`<button class="button button-primary" data-action="apply-import" data-preview="${esc(data.previewId)}">${tr('Aplicar importación revisada','Apply reviewed import')}</button>`:''}</section>`;return}
if(id==='core-status-form'){if(!form.reportValidity())return;const recordId=String(fields.get('recordId')||'');if(!recordId){notify(tr('Selecciona un individuo de los resultados.','Select an individual from the results.'),'error');return}const record=state.quickRecord;if(!record||String(record.id)!==recordId){notify(tr('La selección cambió. Busca el individuo otra vez.','Selection changed. Search for the individual again.'),'error');return}const kind=form.dataset.kind,date=dateSerial(fields.get('date'));if(!date){notify('Fecha inválida.','error');return}const values=kind==='death'?{Death_date:date}:{Preservation_date:date};if(kind==='death'&&record.sheet==='Insectary_data'&&fields.get('cause'))values.Death_cause=String(fields.get('cause'));if(kind==='preserve'){values.Preservation_medium=String(fields.get('medium'));if(record.sheet==='Insectary_data'&&fields.get('condition'))values.Preserved_Dead_Alive=String(fields.get('condition'))}const result=await request('/api/actions',{method:'POST',body:{type:kind==='death'?'death':'preservation',recordId,values,reason:String(fields.get('reason'))},queue:true});clearDraft(`quick:core-status-form:${kind}`);notify(result.queued?tr('Cambio pendiente sin conexión.','Change pending offline.'):statusLabel(result.status||'saved'));if(result.queued){updateFormState(tr('Pendiente sin conexión','Pending offline'));return}route(`/record/${encodeURIComponent(result.records?.[0]?.id||recordId)}`);return}
if(id==='capture-form'){if(!form.reportValidity())return;const values=Object.fromEntries(fields);const visitId=String(values.visitId||'').trim();delete values.visitId;for(const key of Object.keys(values))if(values[key]==='')delete values[key];if(values.Collection_date)values.Collection_date=dateSerial(values.Collection_date);const module=moduleForSheet('Collection_data');const result=await request('/api/records',{method:'POST',body:{module:module.id,values},queue:true});if(state.captureSource||visitId){try{await request('/api/events',{method:'POST',body:{kind:'capture_encounter',recordId:state.captureSource?.id||(result.record?.id||undefined),values:{fieldMark:values.FieldMark_ID,visitId:visitId||undefined,newRecordId:result.record?.id||undefined,linkedIndividualId:state.captureSource?.id||undefined,disposition:values.Release_Collect||undefined,date:values.Collection_date}},queue:true})}catch(error){notify(tr('La fila se guardó, pero el vínculo de encuentro requiere revisión.','The row was saved, but the encounter link needs review.'),'error')}}clearDraft('quick:capture-form:');state.captureSource=null;notify(result.queued?tr('Captura pendiente sin conexión.','Capture pending offline.'):statusLabel(result.status||'saved'));if(result.queued)return;route(`/record/${encodeURIComponent(result.record.id)}`);return}
if(id==='emergence-form'){if(!form.reportValidity())return;const count=Math.min(50,Math.max(1,Number(fields.get('count')||1)));const clutch=String(fields.get('clutch')||'').trim(),date=dateSerial(fields.get('date'));const records=Array.from({length:count},(_,i)=>({module:'Insectary_data',values:{'CLUTCH NUMBER':clutch,LIFESTAGE:'Adult',Wild_Reared:'Reared',Intro2Insectary_date:date,...(fields.get(`sex-${i}`)?{Sex:fields.get(`sex-${i}`)}:{})}}));const body={type:'emergence',records,reason:`Emergencia de ${count} adultos del clutch ${clutch}`,requestId:requestId()};await submitEmergenceBatch(body);return}
}
let draftTimer=0,lookupTimer=0;
async function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file)})}
async function handleFileInput(input){const file=input.files?.[0];if(!file)return;if(input.id==='attachment-input'){if(file.size>10*1024*1024)throw new Error('El archivo supera el límite de 10 MB.');const dataBase64=await fileToBase64(file);await request('/api/attachments',{method:'POST',body:{recordId:input.dataset.record,name:file.name,mimeType:file.type||'application/octet-stream',dataBase64}});notify('Archivo guardado.');renderRoute();return}if(['chat-photo-input','chat-voice-input'].includes(input.id)){const image=input.id==='chat-photo-input';const path=image?'/api/ai/extract':'/api/ai/transcribe';const dataBase64=await fileToBase64(file);const result=await request(path,{method:'POST',body:{dataBase64,mimeType:file.type||'application/octet-stream'}});const draft=result.text||result.transcript||'';const chat=document.getElementById('chat-input');if(chat){chat.value=[chat.value,draft].filter(Boolean).join('\n\n');chat.focus();notify(tr('Borrador añadido para revisión.','Draft added for review.'))}return}}
async function lookupCore(query,kind){const host=document.getElementById('core-search-results');if(!host)return;if(query.length<2){host.innerHTML='';return}host.innerHTML=loading();try{const data=await request(`/api/records?q=${encodeURIComponent(query)}&limit=15`);const candidates=(data.records||[]).filter(r=>['Collection_data','Insectary_data'].includes(r.sheet));host.innerHTML=candidates.length?candidates.map(r=>`<button type="button" class="candidate" data-action="select-core-record" data-id="${esc(r.id)}"><strong>${esc(recordTitle(r,moduleForSheet(r.sheet)))}</strong><small>${esc(r.sheet)} · fila ${esc(r.row||'—')} · ${esc(primaryValues(r,moduleForSheet(r.sheet),2).map(v=>`${v.label}: ${v.value}`).join(' · '))}</small></button>`).join(''):empty('No hay individuos que coincidan.');state.coreCandidates=candidates}catch(error){host.innerHTML=errorBox(error)}}
async function lookupCapture(query){const host=document.getElementById('capture-candidates');if(!host)return;if(query.length<2){host.innerHTML='';return}try{const data=await request(`/api/records?q=${encodeURIComponent(query)}&limit=10`);const candidates=(data.records||[]).filter(r=>r.sheet==='Collection_data'&&r.observed!==false);state.captureCandidates=candidates;host.innerHTML=candidates.length?`<div class="candidate-warning">${icon('alert',17)} <strong>${tr('Posibles coincidencias de marca','Possible mark matches')}</strong><p>${tr('Revisa si es una recaptura antes de crear otra fila.','Check whether this is a recapture before creating another row.')}</p>${candidates.map(r=>`<div class="capture-candidate"><a href="#/record/${encodeURIComponent(r.id)}">${esc(recordTitle(r))} · ${tr('fila','row')} ${esc(r.row||'—')} ${icon('chevron',14)}</a><button type="button" class="button button-small" data-action="select-capture-source" data-id="${esc(r.id)}">${tr('Vincular recaptura','Link recapture')}</button></div>`).join('')}</div>`:''}catch{host.innerHTML=''}}
async function lookupClutch(query){const host=document.getElementById('emergence-candidates');if(!host)return;if(query.length<1){host.innerHTML='';return}try{const data=await request(`/api/records?sheet=Insectary_stocks&q=${encodeURIComponent(query)}&limit=8`);host.innerHTML=(data.records||[]).length?`<div class="candidate-warning"><strong>${tr('Clutches encontrados','Matching clutches')}</strong>${data.records.map(r=>`<button type="button" class="candidate" data-action="select-clutch" data-clutch="${esc(r.values?.['CLUTCH NUMBER']||'')}" data-species="${esc(r.values?.SPECIES||'')}">${esc(recordTitle(r))} · ${esc(r.values?.SPECIES||'')}</button>`).join('')}</div>`:''}catch{host.innerHTML=''}}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();try{if(button.dataset.action==='select-core-record'){const r=state.coreCandidates?.find(item=>String(item.id)===button.dataset.id);if(!r)return;state.quickRecord=r;document.getElementById('core-record-id').value=r.id;document.getElementById('core-selected').innerHTML=`<div class="selected-record">${icon('check',17)}<div><strong>${esc(recordTitle(r,moduleForSheet(r.sheet)))}</strong><small>${esc(r.sheet)} · fila ${esc(r.row||'—')} · ID ${esc(r.id)}</small></div></div>`;document.getElementById('core-search-results').innerHTML='';updateFormState(tr('Individuo seleccionado','Individual selected'));return}
if(button.dataset.action==='select-capture-source'){const r=state.captureCandidates?.find(item=>String(item.id)===button.dataset.id);if(!r)return;state.captureSource=r;const host=document.getElementById('capture-candidates');host.innerHTML=`<div class="selected-record">${icon('check',17)} <div><strong>${tr('Recaptura vinculada a','Recapture linked to')} ${esc(recordTitle(r))}</strong><small>${esc(r.sheet)} · ${tr('fila','row')} ${esc(r.row||'—')}</small></div></div>`;return}
if(button.dataset.action==='select-clutch'){document.getElementById('emergence-clutch').value=button.dataset.clutch;document.getElementById('emergence-species').value=button.dataset.species;document.getElementById('emergence-candidates').innerHTML='';return}
if(button.dataset.action==='open-knowledge'){const data=await request(`/api/knowledge/${encodeURIComponent(button.dataset.id)}`);const doc=data.document||data;modal(doc.title||'Documento',`<div class="knowledge-text">${esc(doc.text||doc.content||'')}</div>${doc.sourceUrl&&safeHref(doc.sourceUrl)?`<a href="${esc(safeHref(doc.sourceUrl))}" target="_blank" rel="noopener noreferrer">Abrir fuente</a>`:''}`);return}
if(button.dataset.action==='load-more-records'){const offset=Number(button.dataset.offset||0),q=button.dataset.q||'';const data=await request(`/api/records?limit=30&offset=${offset}${q?`&q=${encodeURIComponent(q)}`:''}`);const list=document.getElementById('record-list');if(list){const wrap=document.createElement('div');wrap.innerHTML=recordList(data.records||[]);wrap.querySelectorAll('.record-row').forEach(row=>list.append(row));button.dataset.offset=String(offset+30);if(offset+30>=data.total)button.remove()}return}
await handleAction(button,event)}catch(error){notify(error.message||'Ocurrió un error.','error')}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const button=form.querySelector('[type="submit"]');if(button)button.disabled=true;try{await handleSubmit(form)}catch(error){notify(error.message||'No se pudo guardar.','error');if(form.id==='auth-form')renderAuth(!!form.elements.token,error.message)}finally{if(button?.isConnected)button.disabled=false}});
document.addEventListener('input',event=>{const target=event.target;if(!(target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement||target instanceof HTMLSelectElement))return;const form=target.closest('form');if(form?.id==='record-form'){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{const m=mod(form.dataset.module);const raw={};for(const field of m?.fields||[]){const key=field.key||field.name;const input=Array.from(form.elements).find(el=>el.name===key);if(input&&!input.readOnly&&!input.disabled)raw[key]=input.type==='checkbox'?input.checked:input.value}saveDraft(`record:${m.id}:${form.dataset.record}`,raw);updateFormState(tr('Borrador guardado en este dispositivo','Draft saved on this device'))},500)}
if(form?.id==='event-form'){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{saveDraft(`event:${form.dataset.kind}`,{...Object.fromEntries(new FormData(form)),recordId:document.getElementById('event-record-id')?.value||''});updateFormState(tr('Borrador guardado en este dispositivo','Draft saved on this device'))},500)}
if(['core-status-form','capture-form','emergence-form'].includes(form?.id)){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{saveDraft(`quick:${form.id}:${form.dataset.kind||''}`,Object.fromEntries(new FormData(form)));updateFormState(tr('Borrador guardado en este dispositivo','Draft saved on this device'))},500)}
if(target.id==='core-record-search'){clearTimeout(lookupTimer);lookupTimer=setTimeout(()=>lookupCore(target.value.trim()),250)}
if(target.id==='capture-mark'){clearTimeout(lookupTimer);lookupTimer=setTimeout(()=>lookupCapture(target.value.trim()),250)}
if(target.id==='emergence-clutch'){clearTimeout(lookupTimer);lookupTimer=setTimeout(()=>lookupClutch(target.value.trim()),250)}
if(target.id==='emergence-count')renderBatchIndividuals();
});
document.addEventListener('change',async event=>{const input=event.target;if(input instanceof HTMLInputElement&&input.name==='SPECIES')refreshSubspeciesOptions(input.form);if(input instanceof HTMLInputElement&&input.type==='file'){try{await handleFileInput(input)}catch(error){notify(error.message||'No se pudo procesar el archivo.','error')}}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){event.preventDefault();document.querySelector('[data-action="search-focus"]')?.click()}if(event.key==='Escape'){document.getElementById('dialog')?.close();document.getElementById('dialog')?.remove()}});
window.addEventListener('hashchange',()=>{document.getElementById('dialog')?.remove();renderRoute()});
window.addEventListener('online',async()=>{if(!state.user)return;notify(tr('Conexión restablecida. Verificando sesión.','Connection restored. Checking session.'));const ok=await loadSession();if(ok&&!state.offlineResume){await flushOutbox(()=>{});renderRoute()}});
window.addEventListener('offline',()=>{if(state.user)renderRoute()});
window.addEventListener('ithomiini:local-change',()=>{const chip=document.querySelector('.pending-chip');if(chip)chip.innerHTML=`${icon('sync',15)} ${getOutbox().length} ${t('pending')}`});
document.documentElement.lang=state.lang;
if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register(new URL('./sw.js',import.meta.url)).catch(()=>{});
loadSession().then(ok=>{if(ok){renderRoute();if(navigator.onLine&&!state.offlineResume)flushOutbox(()=>{}).then(()=>{if(getOutbox().length)renderRoute()})}});
